import sys
from collections import defaultdict
import heapq

def dfs(u, p, dist, g):
    for v, w in g[u]:
        if v != p:
            dist[v] = dist[u] + w
            dfs(v, u, dist, g)

def dijkstra(start, n, g):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in g[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    return dist

def solve(n, edges, q, ls):
    g = defaultdict(list)
    for x, y, v in edges:
        g[x].append((y, v))
        g[y].append((x, v))

    leafs = [u for u in range(1, n + 1) if len(g[u]) == 1]
    max_dist_from_leaf = [0] * (n + 1)

    for leaf in leafs:
        dist = [0] * (n + 1)
        dfs(leaf, -1, dist, g)
        for i in range(1, n + 1):
            max_dist_from_leaf[i] = max(max_dist_from_leaf[i], dist[i])

    answers = []
    for l in ls:
        count = 0
        visited = [False] * (n + 1)
        for u in range(1, n + 1):
            if not visited[u]:
                dist = dijkstra(u, n, g)
                valid = True
                for v in range(1, n + 1):
                    if dist[v] <= l:
                        visited[v] = True
                    elif max_dist_from_leaf[v] - dist[v] > l:
                        valid = False
                        break
                if valid:
                    count += sum(not visited[v] for v in range(1, n + 1) if dist[v] <= l)
        answers.append(count)

    return answers

input = sys.stdin.read().split()
n = int(input[0])
edges = [(int(input[i]), int(input[i + 1]), int(input[i + 2])) for i in range(1, 3 * n - 2, 3)]
q = int(input[3 * n - 2])
ls = list(map(int, input[3 * n - 1:]))
answers = solve(n, edges, q, ls)
for answer in answers:
    print(answer)
